169	func (s *Server) payError(w http.ResponseWriter, err error) {
170		var decline *payments.DeclineError
171		switch {
172		case errors.As(err, &decline):
173			writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
174		case errors.Is(err, payments.ErrAlreadyPaid):
175			writeError(w, http.StatusConflict, "already_paid", err.Error())
176		case errors.Is(err, payments.ErrInvoiceVoid):
177			writeError(w, http.StatusConflict, "invoice_void", err.Error())
178		case errors.Is(err, payments.ErrNoPaymentMethod):
179			writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
180		case errors.Is(err, payments.ErrUnavailable):
181			writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
182		default:
183			s.storeError(w, err)
184		}
185	}
